effect.shader:
void main(){
vec2 uv=acScreenNorm,p=uv-0.5; float c=cos(direction),s=sin(direction);
vec2 a=mat2(c,-s,s,c)*p;
float wx=a.x*frequency*6.2831853+phase, wy=a.y*frequency*4.4428829-phase*0.7;
float z=(sin(wx)+0.55*cos(wy))*amplitude;
vec2 warped=a+vec2(cos(wx),-sin(wy))*z*0.48;
vec2 q=mat2(c,s,-s,c)*warped+0.5;
float valid=step(0.0,q.x)*step(q.x,1.0)*step(0.0,q.y)*step(q.y,1.0);
vec4 src=texture2DCv(inputImg.texture,uv),dst=texture2DCv(inputImg.texture,clamp(q,0.0,1.0));
vec2 slope=vec2(cos(wx),-0.55*sin(wy))*amplitude*frequency;
float light=clamp(0.76+dot(normalize(vec3(-slope,1.0)),normalize(vec3(-0.4,-0.5,1.0)))*0.42,0.35,1.35);
dst.rgb*=mix(1.0,light,lighting);
gl_FragColor=mix(src,dst,mixAmount*valid);
}
